parameters.jsCode:
const input = $input.first().json;
const message = String(input.message ?? '').replace(/\s+/g, ' ').trim();
const subject = String(input.subject ?? '').replace(/\s+/g, ' ').trim();
const missing = ['ticketId', 'from', 'message'].filter((field) => input[field] === undefined || input[field] === null || String(input[field]).trim() === '');
return [{ json: { ...input, message, subject, messageLength: message.length, missingFields: missing, inputValid: missing.length === 0 && message.length >= 10 } }];

const ticket = $input.first().json;
const text = (ticket.subject + ' ' + ticket.message).toLowerCase();
const escalationReasons = [];
if (!ticket.inputValid) escalationReasons.push('Missing required support context or message is too short');
if (/refund|chargeback|cancel.*subscription|payment/.test(text)) escalationReasons.push('Billing or refund request requires human review');
if (/password|login|log in|account access|reset token/.test(text)) escalationReasons.push('Account access request requires human review');
if (/furious|angry|useless|legal action|lawsuit|complaint/.test(text)) escalationReasons.push('Negative or escalated language requires human review');
const matchedKnowledge = (ticket.knowledgeBase ?? []).filter((entry) => {
  const words = entry.title.toLowerCase().split(/\s+/).filter((word) => word.length > 3);
  return words.some((word) => text.includes(word));
});
const knowledgeContext = matchedKnowledge.length ? matchedKnowledge : (ticket.knowledgeBase ?? []).slice(0, 3);
return [{ json: { ...ticket, escalationReasons, policyReviewRequired: escalationReasons.length > 0, knowledgeContext } }];

