Ticket ID: {{$json.ticketId}}
From: {{$json.from}}
Subject: {{$json.subject}}
Message: {{$json.message}}
Input valid: {{$json.inputValid}}
Policy review required: {{$json.policyReviewRequired}}
Policy reasons: {{$json.escalationReasons}}
Demo knowledge context: {{$json.knowledgeContext}}

parameters.jsCode:
const ticket = $items('Support Policy Gate')[0].json;
const raw = String($input.first().json.text ?? $input.first().json.response ?? '');
let parsed;
try {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  parsed = JSON.parse(cleaned);
} catch (error) {
  parsed = { category: 'general', priority: 'medium', sentiment: 'neutral', suggestedReply: 'Thanks for contacting support. We received your message and will review it before replying.', knowledgeUsed: [] };
}
const reasons = Array.isArray(ticket.escalationReasons) ? [...ticket.escalationReasons] : [];
if (!parsed.suggestedReply) reasons.push('No usable draft reply was returned');
const needsHumanReview = ticket.policyReviewRequired || reasons.length > 0 || !ticket.inputValid;
return [{ json: { ticketId: ticket.ticketId, from: ticket.from, subject: ticket.subject, message: ticket.message, category: parsed.category ?? 'general', priority: parsed.priority ?? 'medium', sentiment: parsed.sentiment ?? 'neutral', suggestedReply: parsed.suggestedReply ?? '', needsHumanReview, escalationReason: reasons.length ? reasons.join('; ') : null, knowledgeUsed: parsed.knowledgeUsed ?? [], safetyNote: 'Draft only. No support message was sent and no external system was called.' } }];
